// ==== modal_excluir_global.js ====
// Modal global para exclusão (padronizado com active class)
(function() {
    function initModal() {
        const modal = document.getElementById("modalConfirmacao");
        if (!modal) return;
        
        window.abrirModal = function({ titulo, texto, onConfirm }) {
            const modalEl = document.getElementById("modalConfirmacao");
            const btnCancelar = document.getElementById("btnCancelar");
            const btnConfirmar = document.getElementById("btnConfirmar");
            const tituloEl = document.getElementById("modalTitulo");
            const textoEl = document.getElementById("modalTexto");

            if (!modalEl || !btnCancelar || !btnConfirmar) return;

            tituloEl.textContent = titulo;
            textoEl.textContent = texto;

            modalEl.classList.add('active');

            const newConfirmBtn = btnConfirmar.cloneNode(true);
            const newCancelBtn = btnCancelar.cloneNode(true);
            
            btnConfirmar.parentNode.replaceChild(newConfirmBtn, btnConfirmar);
            btnCancelar.parentNode.replaceChild(newCancelBtn, btnCancelar);

            let bloqueio = false;

            newConfirmBtn.onclick = async () => {
                if (bloqueio) return;
                bloqueio = true;
                
                const originalText = newConfirmBtn.innerText;
                newConfirmBtn.innerText = "Processando...";

                try {
                    if (onConfirm) await onConfirm();
                    modalEl.classList.remove('active');
                } catch (error) {
                    alert("Erro: " + error.message);
                } finally {
                    newConfirmBtn.innerText = originalText;
                    bloqueio = false;
                }
            };

            newCancelBtn.onclick = () => {
                modalEl.classList.remove('active');
            };

            modalEl.onclick = (e) => {
                if (e.target === modalEl) modalEl.classList.remove('active');
            };
        };
    }
    
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initModal);
    } else {
        initModal();
    }
})();

// ==== btn_excluir.js ====
document.addEventListener('DOMContentLoaded', () => {

    document.querySelectorAll('.btn-excluir').forEach(btn => {

        btn.addEventListener('click', () => {

            const id = btn.dataset.id;
            const descricao = btn.dataset.desc;

            if (typeof window.abrirModal === 'undefined') {
                Notificacao.erro("Erro ao carregar modal.");
                return;
            }

            window.abrirModal({
                titulo: "Inativar Tarefa",
                texto: `Deseja inativar a tarefa: "${descricao}"?`,
                textoConfirmacao: "Sim, inativar",
                textoCancela: "Cancelar",

                onConfirm: async () => {
                    try {
                        const htmlOriginal = btn.innerHTML;

                        btn.disabled = true;
                        btn.style.opacity = '0.5';
                        btn.innerHTML = '⏳';

                        const response = await fetch(`/tarefas/excluir/${id}`, {
                            method: "POST",
                            headers: {
                                'X-Requested-With': 'XMLHttpRequest'
                            }
                        });

                        const data = await response.json();

                        if (data.success) {

                            const linha = btn.closest('tr');

                            linha.style.transition = 'opacity 0.3s, transform 0.3s';
                            linha.style.opacity = '0';
                            linha.style.transform = 'translateX(50px)';

                            setTimeout(() => {
                                linha.remove();
                                atualizarContadorTarefas();
                            }, 300);

                            Notificacao.sucesso(data.message);

                        } else {
                            throw new Error(data.error);
                        }

                    } catch (error) {
                        Notificacao.erro(error.message || 'Erro ao inativar');

                        btn.disabled = false;
                        btn.style.opacity = '1';
                        btn.innerHTML = '<i class="bi bi-trash"></i>';
                    }
                }
            });

        });

    });

});

function atualizarContadorTarefas() {
    const tabela = document.querySelector('.custom-table tbody');
    const linhas = tabela.querySelectorAll('tr:not(.text-center)');
    const contador = document.querySelector('.status-direita .badge-pure');

    if (contador) {
        const total = linhas.length;
        contador.textContent = total + ' tarefas';

        if (total === 0) {
            tabela.innerHTML = `
                <tr>
                    <td colspan="9" class="text-center py-4 text-white-50">
                        Nenhuma tarefa cadastrada ou nesse período
                    </td>
                </tr>
            `;
        }
    }
}

// ==== concluir_tarefas.js ====
let botaoAtual = null;

document.addEventListener('DOMContentLoaded', () => {

    const form = document.getElementById('formConcluir');
    const overlay = document.getElementById('modalConcluir');

    if (!form || !overlay) return;

    let enviando = false;

    // 🔥 CLICK BOTÃO
    document.querySelectorAll('.btn-concluir').forEach(btn => {
        btn.addEventListener('click', () => {

            botaoAtual = btn;

            const url = btn.getAttribute('data-url');
            form.action = url;

            overlay.classList.add('active');
        });
    });

    // 🔥 SUBMIT
    form.addEventListener('submit', async (e) => {
        e.preventDefault();

        if (enviando) return;
        enviando = true;

        const btnSubmit = form.querySelector('button[type="submit"]');
        const htmlOriginal = btnSubmit.innerHTML;

        btnSubmit.disabled = true;
        btnSubmit.innerHTML = '⏳';

        try {
            const response = await fetch(form.action, {
                method: "POST",
                body: new FormData(form),
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });

            const data = await response.json();

            if (!data.success) {
                throw new Error(data.error || 'Erro ao concluir');
            }

            // 🔥 LINHA DA TABELA
            const linha = botaoAtual?.closest('tr');

            if (linha) {

                const celulaStatus = linha.querySelector('td:nth-child(3)');
                const celulaFinalizacao = linha.querySelector('td:nth-child(6)');

                if (celulaStatus) {
                    celulaStatus.innerHTML =
                        `<span class="badge-pure bg-success">✅ Concluída</span>`;
                }

                if (celulaFinalizacao && data.data_finalizacao) {
                    celulaFinalizacao.innerHTML =
                        `<span class="badge-pure bg-success">${data.data_finalizacao}</span>`;
                }

                // remove todos botões de ação da linha
                linha.querySelectorAll('.btn-concluir, .btn-excluir, .btn-acao.edit').forEach(b => b.remove());
            }

            Notificacao.sucesso(data.message);

            fecharModalConcluir();
            form.reset();

        } catch (error) {
            Notificacao.erro(error.message || 'Erro ao concluir');
        }

        btnSubmit.disabled = false;
        btnSubmit.innerHTML = htmlOriginal;
        enviando = false;
    });

});


// 🔥 FUNÇÃO GLOBAL (evita teu erro "not defined")
window.fecharModalConcluir = function () {
    const overlay = document.getElementById('modalConcluir');
    if (overlay) {
        overlay.classList.remove('active');
    }
};

// ==== detalhes_completo.js ====
function verDetalhes(tarefaId) {
    const modal = document.getElementById('modalDetalhesTarefa');
    const conteudo = document.getElementById('conteudoDetalhes');
    
    conteudo.innerHTML = `
        <div style="text-align: center; padding: 30px; color: var(--texto-mutado);">
            <div class="spinner-pure"></div>
            <p style="margin-top: 10px; font-size: var(--fs-micro);">Carregando dados da tarefa...</p>
        </div>
    `;
    
    modal.classList.add('active');
    
    fetch(`/tarefas/detalhes/${tarefaId}`)
        .then(response => response.json())
        .then(data => {
            if (data.error) {
                conteudo.innerHTML = `<div class="badge-pure bg-danger" style="width: 100%; padding: 10px;">${data.error}</div>`;
                return;
            }
            
            const statusIcon = data.status === 'concluido' ? '✅' : (data.status === 'em andamento' ? '⏳' : '⏰');
            document.getElementById('modalTitulo').innerHTML = `${statusIcon} ${data.titulo}`;
            
            conteudo.innerHTML = `
                <div class="modal-detalhes-field full-width" style="margin-bottom: 12px;">
                    <div class="field-detalhes-label" style="color: var(--cor-marca); font-weight: 600;">📝 Descrição Detalhada</div>
                    <div class="field-detalhes-value-scroll" style="font-size: var(--fs-pequeno);">${data.descricao || '<span style="opacity: 0.5;">Sem descrição.</span>'}</div>
                </div>
                
                <div class="modal-detalhes-grid" style="font-size: var(--fs-pequeno);">
                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📊 Status</div>
                        <div class="field-detalhes-value"><span class="badge-pure ${data.status === 'concluido' ? 'bg-success' : (data.status === 'em andamento' ? 'bg-warning text-dark' : 'bg-danger')}">${data.status_label}</span></div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">⚡ Prioridade</div>
                        <div class="field-detalhes-value"><span class="badge-pure ${data.prioridade === 'alta' ? 'bg-danger' : (data.prioridade === 'media' ? 'bg-warning text-dark' : 'bg-success')}">${data.prioridade_label}</span></div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">🏷️ Categoria</div>
                        <div class="field-detalhes-value">
                            <span class="badge-pure" style="background-color: ${data.categoria_cor || 'var(--border-sutil)'}; color: white;">
                                ${data.categoria}
                            </span>
                        </div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📅 Data Início</div>
                        <div class="field-detalhes-value">${data.data_inicio}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">⏰ Data Prazo</div>
                        <div class="field-detalhes-value">${data.data_final}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">✅ Data Conclusão</div>
                        <div class="field-detalhes-value">${data.data_finalizacao !== '-' ? data.data_finalizacao : '<span style="opacity: 0.5;">Não concluída</span>'}</div>
                    </div>
                </div>

                <div class="modal-detalhes-field full-width">
                    <div class="field-detalhes-label">💬 Motivo da Conclusão</div>
                    <div class="field-detalhes-value" style="font-style: italic; color: var(--texto-discreto);">
                        ${data.motivo_conclusao ? data.motivo_conclusao : '<span style="opacity: 0.5;">Sem observações.</span>'}
                    </div>
                </div>
            `;
        })
        .catch(error => {
            console.error('Erro:', error);
            conteudo.innerHTML = `<div class="badge-pure bg-danger" style="width: 100%; padding: 10px;">Erro ao carregar detalhes</div>`;
        });
}

function fecharModalDetalhes(event) {
    // ✅ CORRIGIDO: usa a classe correta do modal de detalhes
    if (!event || event.target.classList.contains('modal-detalhes-overlay')) {
        document.getElementById('modalDetalhesTarefa').classList.remove('active');
    }
}

// ==== totalizadores.js ====
// Totalizadores da Tela de Tarefas
(function() {
    'use strict';

    function calcularTotaisTarefas() {
        const tabela = document.querySelector('.custom-table');
        if (!tabela) return;

        const linhas = tabela.querySelectorAll('tbody tr');
        let pendentes = 0;
        let andamento = 0;
        let concluidas = 0;

        linhas.forEach(linha => {
            // Pula a linha de "nenhuma tarefa"
            if (linha.querySelector('td[colspan]')) return;

            const colunas = linha.querySelectorAll('td');
            if (colunas.length < 3) return;

            // Coluna STATUS é a terceira (índice 2)
            const statusText = colunas[2]?.innerText || '';

            if (statusText.includes('Pendente')) {
                pendentes++;
            } else if (statusText.includes('Andamento')) {
                andamento++;
            } else if (statusText.includes('Concluída')) {
                concluidas++;
            }
        });

        // Atualiza os spans
        const spanPendentes = document.getElementById('totalPendentes');
        const spanAndamento = document.getElementById('totalAndamento');
        const spanConcluidas = document.getElementById('totalConcluidas');

        if (spanPendentes) spanPendentes.innerText = pendentes;
        if (spanAndamento) spanAndamento.innerText = andamento;
        if (spanConcluidas) spanConcluidas.innerText = concluidas;
    }

    // Executa quando a página carregar
    document.addEventListener('DOMContentLoaded', function() {
        calcularTotaisTarefas();

        // Observa mudanças na tabela
        const observer = new MutationObserver(function() {
            calcularTotaisTarefas();
        });

        const tabela = document.querySelector('.custom-table');
        if (tabela) {
            observer.observe(tabela, { childList: true, subtree: true });
        }

        // Quando o formulário de filtros for enviado, recalcula
        const formFiltros = document.querySelector('.form-filtros-total');
        if (formFiltros) {
            formFiltros.addEventListener('submit', function() {
                setTimeout(calcularTotaisTarefas, 300);
            });
        }
    });
})();

// ==== ordenacao.js ====
// Ordenação de colunas na tabela de Tarefas
(function() {
    'use strict';
    
    let colunaAtual = null;
    let ordemAtual = 'asc';
    
    function ordenarTabela(colunaIndex, tipo) {
        const tabela = document.querySelector('.custom-table tbody');
        if (!tabela) return;
        
        const linhas = Array.from(tabela.querySelectorAll('tr'));
        
        // Filtra linhas válidas (ignora mensagem "nenhuma tarefa")
        const linhasValidas = linhas.filter(linha => {
            return !linha.querySelector('td[colspan]');
        });
        
        // Ordena as linhas
        linhasValidas.sort((a, b) => {
            let valorA = a.children[colunaIndex]?.innerText.trim() || '';
            let valorB = b.children[colunaIndex]?.innerText.trim() || '';
            
            // Converte para número se for coluna numérica
            if (tipo === 'numero') {
                valorA = parseInt(valorA) || 0;
                valorB = parseInt(valorB) || 0;
            }
            // Converte para data se for data
            else if (tipo === 'data') {
                valorA = valorA ? new Date(valorA.split('/').reverse().join('-')) : new Date(0);
                valorB = valorB ? new Date(valorB.split('/').reverse().join('-')) : new Date(0);
            }
            // Converte para texto (padrão)
            else {
                valorA = valorA.toLowerCase();
                valorB = valorB.toLowerCase();
            }
            
            if (valorA < valorB) return ordemAtual === 'asc' ? -1 : 1;
            if (valorA > valorB) return ordemAtual === 'asc' ? 1 : -1;
            return 0;
        });
        
        // Reconstroi a tabela
        linhasValidas.forEach(linha => tabela.appendChild(linha));
        
        // Mantém as linhas de mensagem no final
        const linhasMensagem = linhas.filter(linha => linha.querySelector('td[colspan]'));
        linhasMensagem.forEach(linha => tabela.appendChild(linha));
    }
    
    function initOrdenacao() {
        const cabecalhos = document.querySelectorAll('.custom-table th');
        
        // Tipos de cada coluna da tabela de Tarefas
        const tiposColunas = [
            { index: 0, tipo: 'numero', nome: 'Nº REG.' },
            { index: 1, tipo: 'texto', nome: 'TÍTULO' },
            { index: 2, tipo: 'texto', nome: 'STATUS' },
            { index: 3, tipo: 'data', nome: 'DATA INICIO' },
            { index: 4, tipo: 'data', nome: 'DATA FINAL' },
            { index: 5, tipo: 'data', nome: 'DATA FINALIZAÇÃO' },
            { index: 6, tipo: 'texto', nome: 'CATEGORIA' },
            { index: 7, tipo: 'texto', nome: 'PRIORIDADE' }
        ];
        
        cabecalhos.forEach((th, idx) => {
            // Adiciona classe sortable
            th.classList.add('sortable');
            
            // Encontra o tipo da coluna
            const colunaInfo = tiposColunas.find(c => c.index === idx);
            if (!colunaInfo) return;
            
            th.addEventListener('click', () => {
                // Reseta as setas das outras colunas
                cabecalhos.forEach(h => {
                    h.classList.remove('asc', 'desc');
                });
                
                // Alterna a ordem
                if (colunaAtual === idx) {
                    ordemAtual = ordemAtual === 'asc' ? 'desc' : 'asc';
                } else {
                    colunaAtual = idx;
                    ordemAtual = 'asc';
                }
                
                // Adiciona classe para mostrar a seta
                th.classList.add(ordemAtual === 'asc' ? 'asc' : 'desc');
                
                // Ordena
                ordenarTabela(idx, colunaInfo.tipo);
            });
        });
    }
    
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initOrdenacao);
    } else {
        initOrdenacao();
    }
})();

